css:
.container {
  --bg-size: 48px;
  height: 100%;
  width: 100%;
  display: flex;
  background-image: repeating-conic-gradient(
      from 0deg at 0% 0%,
      #8e1d9e 0deg,
      #8ca6db 5deg
    ),
    repeating-conic-gradient(from 0deg at 100% 100%, #8ca6db 0deg, #8e1d9e 5deg);
  background-size: var(--bg-size) var(--bg-size);
  background-blend-mode: screen;
}
